public class AppendSeriesSkill
{
    /// <summary>
    /// Append a series of elements to the chart.
    /// chart_id: Name of the GameObject containing the BaseChart component.
    /// x_values: List of X values — used as category labels (category axis) or parsed as numeric X coordinates (value axis).
    /// y_values: List of Y values to append (each parsed as double). Must be same length as x_values.
    /// serieIndex: Index of the serie to append data to.
    /// </summary>
    public static void Execute(string chart_id, List<string> x_values, List<string> y_values, int serieIndex)
    {
        Debug.Log("Executing AppendSeriesSkill logic...");

        // Validate chart_id
        if (string.IsNullOrEmpty(chart_id))
        {
            Debug.LogWarning("AppendSeriesSkill: chart_id is null or empty.");
            return;
        }

        // Validate that both lists are provided and non-empty
        if (x_values == null || x_values.Count == 0)
        {
            Debug.LogWarning("AppendSeriesSkill: x_values list is null or empty.");
            return;
        }

        if (y_values == null || y_values.Count == 0)
        {
            Debug.LogWarning("AppendSeriesSkill: y_values list is null or empty.");
            return;
        }

        // Validate that both lists have the same length
        if (x_values.Count != y_values.Count)
        {
            Debug.LogWarning($"AppendSeriesSkill: x_values count ({x_values.Count}) does not match y_values count ({y_values.Count}). They must be equal.");
            return;
        }

        // Find the GameObject by chart_id and get the BaseChart component
        GameObject chartObject = GameObject.Find(chart_id);
        if (chartObject == null)
        {
            Debug.LogWarning($"AppendSeriesSkill: GameObject '{chart_id}' not found in the scene.");
            return;
        }

        BaseChart chart = chartObject.GetComponent<BaseChart>();
        if (chart == null)
        {
            Debug.LogWarning($"AppendSeriesSkill: GameObject '{chart_id}' does not have a BaseChart component.");
            return;
        }

        // Validate serie exists
        var serie = chart.GetSerie(serieIndex);
        if (serie == null)
        {
            Debug.LogWarning($"AppendSeriesSkill: Serie {serieIndex} not found on chart '{chart_id}'.");
            return;
        }

        // Check if X axis is category-based
        var xAxis = chart.GetChartComponent<XAxis>();
        bool isCategoryAxis = (xAxis != null && xAxis.IsCategory());

        int appendedCount = 0;

        for (int i = 0; i < x_values.Count; i++)
        {
            string xVal = x_values[i];
            string yVal = y_values[i];

            // Parse y_value to double
            double parsedYValue;
            if (!double.TryParse(yVal, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out parsedYValue))
            {
                Debug.LogWarning($"AppendSeriesSkill: Could not parse y_values[{i}] '{yVal}' as a number. Skipping this entry.");
                continue;
            }

            if (isCategoryAxis)
            {
                // Add x_value as a category label on the X axis
                chart.AddXAxisData(xVal);

                // Add y_value as the data point with x_value as dataName
                chart.AddData(serieIndex, parsedYValue, xVal);
            }
            else
            {
                // Attempt to parse x_value as numeric for (x, y) scatter/line data
                double parsedXValue;
                if (double.TryParse(xVal, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out parsedXValue))
                {
                    chart.AddData(serieIndex, parsedXValue, parsedYValue, xVal);
                }
                else
                {
                    // Non-numeric x on a value axis — add y only with x as dataName
                    Debug.LogWarning($"AppendSeriesSkill: X axis is not category-based and x_values[{i}] '{xVal}' is not numeric. Adding y_value only with x_value as dataName.");
                    chart.AddData(serieIndex, parsedYValue, xVal);
                }
            }

            appendedCount++;
        }

        Debug.Log($"AppendSeriesSkill: Successfully appended {appendedCount} of {x_values.Count} elements to serie {serieIndex} on chart '{chart_id}'.");
        chart.RefreshChart();
    }
}

